import path from "node:path";

const closeDialogs = async (page) => {
  for (let i = 0; i < 5; i++) {
    if (!(await page.locator(".bp3-overlay-open").count())) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(300);
  }
};

const linkSummary = (scope) =>
  scope.evaluate((el) =>
    [...el.querySelectorAll("a")]
      .filter((a) => /View docs|See more/.test(a.textContent))
      .map((a) => ({ text: a.textContent.trim(), href: a.href })),
  );

export default {
  async ready({ page }) {
    await closeDialogs(page);
    return true;
  },
  async run({ page, outDir }) {
    const proof = {};
    await closeDialogs(page);
    await page.keyboard.press("Meta+p");
    await page.keyboard.type("Export Discourse Graph");
    await page.waitForTimeout(500);
    await page.keyboard.press("Enter");

    const dialog = page.locator(".bp3-dialog").filter({ hasText: "Export Discourse Graph" }).last();
    await dialog.waitFor({ timeout: 20000 });
    await dialog.getByRole("tab", { name: "Export" }).click();
    await dialog.getByRole("button", { name: "Export options" }).click();
    await page.waitForTimeout(800);
    proof.exportLinks = await linkSummary(dialog);
    await dialog.screenshot({ path: path.join(outDir, "eng2407-export-options.png") });

    const publish = dialog.getByRole("tab", { name: "Publish" });
    proof.publishTab = (await publish.count()) > 0;
    if (proof.publishTab) {
      await publish.click();
      await page.waitForTimeout(800);
      const callout = dialog.locator(".bp3-callout");
      proof.warningVisible = (await callout.count()) > 0;
      if (proof.warningVisible) {
        proof.warningLinks = await linkSummary(callout.first());
        await dialog.screenshot({ path: path.join(outDir, "eng2407-stored-relations-warning.png") });
      }
    }
    if (!proof.exportLinks.length) throw new Error("No docs links found in Export options");
    if (proof.exportLinks.some((l) => l.text !== "View docs")) throw new Error("Old link text present");
    return proof;
  },
  async cleanup({ page }) {
    await closeDialogs(page);
  },
};
